struct Ready{s:Arc<Setup>,g:Record,o:Arc<Owned>,base:Arc<IterationEnv>,request:String,requests:Vec<(String,Value)>}
fn plan_observe(s:&Setup)->peer_plan_review::Observe{let c=s.config.clone();let st=s.settings.clone();Arc::new(move||Ok((c.clone(),st.clone())))}
fn approve_batch(r:&Ready,lineage:Arc<crate::pet_runtime::lease_controller::PeerRoundPublished>)->Vec<Arc<crate::pet_runtime::lease_controller::message_controller::Approved>>{
 let store=Arc::new(current_store(&r.s));let now=crate::assistant_memory::now();let batch=peer_plan_review::Batch::capture_with_round(&r.o,&r.g,&r.s.config,&r.s.settings,now,Some(lineage)).unwrap().unwrap();let observe=plan_observe(&r.s);let source=Source::capture_peer(r.o.clone(),&r.g,batch.clone(),store.clone(),observe.clone()).unwrap();r.o.yield_for_decision(&store,&source,crate::assistant_memory::now()).unwrap();let d=r.base.decide(source.clone()).unwrap();r.o.resume_after_decision(&store,&source,crate::assistant_memory::now()).unwrap();batch.approve(&d,&r.o,&r.g,&observe,crate::assistant_memory::now()).unwrap()
}
fn prepare(provider:&'static str,steps:u8,ack:bool)->Ready{prepare_in(Arc::new(Setup::new()),provider,steps,ack,false)}
fn prepare_in(mut s:Arc<Setup>,provider:&'static str,steps:u8,ack:bool,uncertain:bool)->Ready{
let native=std::env::var("COUCOU_PEER_RECOVERY_MODE").as_deref()==Ok("partial-native");let deadline=crate::assistant_memory::now()+if native{900_000}else{120_000};let g=s.f.goal_named_criteria(provider,"original-owner-peer-publication-recovery",vec!["Independent verification of actual outcome".into()]);let to=if provider=="ollama"{"ai_lmstudio"}else{"ai_ollama"};
 let first=json!({"kind":"plan","description":"One independent finite branch","steps":[{"description":"Delegate bounded work","postcondition":"Receipt is not verification","operation":{"operationId":"pet.delegate","version":1,"arguments":{"toPetId":to,"subgoal":"Own finite task","criteria":["Own free criterion"],"expiresAt":deadline,"allowance":{"modelCalls":1,"toolCalls":1,"outputBytes":16384},"maxDepth":2}}}]});
 let second=json!({"kind":"plan","description":"Two exact independently reviewed DATA deliveries","steps":(0..steps).map(|i|json!({"description":format!("Exact pending DATA {i}"),"postcondition":"Native receipt, not criterion success","operation":{"operationId":"pet.message","version":1,"arguments":{"toPetId":to,"kind":"request","text":format!("Exact derived DATA {i}; no authority granted"),"expiresAt":deadline}}})).collect::<Vec<_>>()});
 let meta=if provider=="lmstudio"{lm_metadata()}else{metadata()};let(mut server,http)=crate::pet_runtime::lease_controller::memory_test_http_fixture_idle(vec![("application/json",meta.to_string()),("text/event-stream",stream(&first.to_string(),true)),("application/json",meta.to_string()),("text/event-stream",stream(&second.to_string(),!uncertain))],|_|{});server.id=provider;
 if native{
  let endpoint=std::env::var("COUCOU_H3D2_NATIVE_ENDPOINT").expect("explicit loopback native fixture endpoint");assert!(endpoint.starts_with("http://127.0.0.1:"));
  let upstream=PathBuf::from(std::env::var("COUCOU_H3D2_NATIVE_UPSTREAM").expect("explicit private upstream manifest"));assert!(upstream.is_absolute()&&!upstream.exists());fs::write(&upstream,serde_json::to_vec(&json!({"endpoint":server.url})).unwrap()).unwrap();server.url=endpoint;
  let setup=Arc::get_mut(&mut s).expect("generated native profile is uniquely owned before admission");setup.settings.main_pill="ai_ollama".into();setup.settings.chat_provider="ollama".into();setup.settings.ollama_url=server.url.clone();setup.settings.chat_models.insert("ollama".into(),"fixture-free".into());setup.settings.autostart=false;setup.settings.hooks_installed=false;setup.settings.sound_enabled=false;setup.settings.pet_system_center=false;setup.settings.language="pt".into();
  setup.settings.shortcuts=crate::shortcuts::ACTIONS.iter().map(|a|(a.id.to_owned(),crate::shortcuts::Binding{keys:String::new(),enabled:false})).collect();
  fs::write(setup.f.path.join("native-qa-settings.json"),serde_json::to_vec(&setup.settings).unwrap()).unwrap();
 }
 let(g,o)=parent_with_steps(&s,&g,&server,deadline,3,6,2,steps);let base=Arc::new(IterationEnv{s:s.clone(),provider,url:server.url.clone(),owner:o.clone(),approve_data:true,stop_wait:false,approve_derived:true,busy_delivery:false,delivery_blocked:AtomicBool::new(false),store_lock:Mutex::new(None),child_started:AtomicBool::new(false),decisions:AtomicUsize::new(0),waits:AtomicUsize::new(0),child_requests:Mutex::new(vec![])});let store=Arc::new(current_store(&s));
 let _=run(o.plan_once(None,&g,&server,"driver-plan-1",&s.config)).unwrap();let g=o.publish_generated_plan(&store,"driver-plan-1",crate::assistant_memory::now()).unwrap().receipt.record;let observe=plan_observe(&s);let batch=peer_plan_review::Batch::capture(&o,&g,&s.config,&s.settings,crate::assistant_memory::now()).unwrap().unwrap();let source=Source::capture_peer(o.clone(),&g,batch.clone(),store.clone(),observe.clone()).unwrap();o.yield_for_decision(&store,&source,crate::assistant_memory::now()).unwrap();let d=base.decide(source.clone()).unwrap();o.resume_after_decision(&store,&source,crate::assistant_memory::now()).unwrap();for approval in batch.approve(&d,&o,&g,&observe,crate::assistant_memory::now()).unwrap(){o.send_message(&g,&approval,crate::assistant_memory::now(),||Ok((s.config.clone(),s.settings.clone()))).unwrap();}
 let c=s.config.clone();let wait=Source::capture_peer_wait(o.clone(),&g,store.clone(),Arc::new(move||Ok(c.clone()))).unwrap();o.yield_for_decision(&store,&wait,crate::assistant_memory::now()).unwrap();base.child();let input=DelegationInput{pet_id:g.spec.owner.pet_id.clone(),goal_id:g.id.clone(),decision_id:o.lease().decision_id.clone()};let data=Arc::new(peer_round_data::Captured::at(store.root_path(),&s.f.path.join("authority"),input,&server,&o.lease().model,crate::assistant_memory::now()).unwrap());s.a.record_peer_round_feedback(&o.live.spec,&o.live.proof,o.lease(),&g,&data,crate::assistant_memory::now()).unwrap();o.resume_after_decision(&store,&wait,crate::assistant_memory::now()).unwrap();wait.retire();
 let request="driver-plan-2".to_string();let round=o.prepare_peer_round(&g,&server,&request,data,&s.config).unwrap();let review=round.review();let env=base.clone();let observed=o.clone();let observe:peer_round_review::Observe=Arc::new(move||{let c=env.capture(&observed)?;Ok((c.configuration,c.server))});let source=Source::capture_peer_data(o.clone(),&g,review.clone(),store.clone(),observe.clone()).unwrap();o.yield_for_decision(&store,&source,crate::assistant_memory::now()).unwrap();let d=base.decide(source.clone()).unwrap();o.resume_after_decision(&store,&source,crate::assistant_memory::now()).unwrap();let approved=Arc::new(review.approve(d,&o,&g,&observe,crate::assistant_memory::now()).unwrap());let sent=run(o.send_peer_round(None,round,approved.clone()));let requests=http.join().unwrap();assert_eq!(requests.len(),4);
 if uncertain{assert!(sent.is_err(),"missing final stream ACK is not known success");assert_eq!(o.workers(),0);return Ready{s,g,o,base,request,requests};}let output=sent.unwrap();
 // A durable output alone does not authorize an absent canonical plan write.
 let before=s.bytes(&g);assert!(o.reconcile_peer_round_plan(store.clone(),&request,crate::assistant_memory::now()).is_err());assert_eq!(s.bytes(&g),before);assert_eq!(approved.publication_validity(&s.a,&o.live.spec,&o.live.proof,&request,crate::assistant_memory::now()),Validity::Current);
 let gate=o.plan_gate().unwrap();let certificate=s.a.prepare_generated_plan(&o.live.spec,&o.live.proof,o.lease(),&g,&output,&gate,crate::assistant_memory::now()).unwrap();let commit=store.commit_generated(&certificate,crate::assistant_memory::now()).unwrap();let g=commit.receipt.record.clone();drop(commit);drop(certificate);drop(gate);drop(approved);drop(review);drop(source);drop(batch);
 if ack{assert!(o.publish_generated_plan(&store,&request,crate::assistant_memory::now()).unwrap().acknowledged);}assert_eq!(o.workers(),0);Ready{s,g,o,base,request,requests}
}
struct Env{base:Arc<IterationEnv>,pending:usize,delivered:usize}
impl Environment for Env{
 fn capture(&self,o:&Owned)->model::Result<Capture>{self.base.capture(o)}fn configuration(&self)->model::Result<crate::pet_config::Configuration>{self.base.configuration()}fn peer_configuration(&self)->model::Result<(crate::pet_config::Configuration,Settings)>{self.base.peer_configuration()}fn target(&self)->model::Result<Arc<crate::spotify::goal::Target>>{panic!("publication DATA is not System authority")}
 fn notify(&self,s:&Status){self.base.notify(s)}
 fn decide(&self,s:Source)->Option<Decision>{let p=&s.review()["recipe"];assert_eq!(s.target().origin,crate::pet_runtime::recipe_decisions::Origin::GoalPeerPlan);assert_eq!(p["steps"].as_array().unwrap().len(),self.pending);let origin=&p["roundDataProvenance"];assert_eq!(origin["reconciledFromCanonicalPlan"],true);assert_eq!(origin["nativeModelDataApprovalRetained"],false);assert_eq!(origin["canonicalReceiptsAlreadyObserved"].as_array().unwrap().len(),self.delivered);assert!(p["expiresAt"].as_u64().unwrap()<=origin["originalDataExpiresAt"].as_u64().unwrap());self.base.decide(s)}
}
#[test]fn lost_native_data_object_can_ack_only_the_existing_plan_then_review_pending_effects_on_both_engines(){for p in["ollama","lmstudio"]{
 let r=prepare(p,1,false);let before=body(&r.s,&r.g);assert_eq!(before["planningUsage"]["rounds"][1]["publication"]["phase"],"prepared");let env=Arc::new(Env{base:r.base.clone(),pending:1,delivered:0});let driver=Driver::new(r.o.clone(),Arc::new(current_store(&r.s)),env).unwrap();assert!(!driver.status().unwrap().retained_approval);let status=run(driver.run()).unwrap_or_else(|e|panic!("{e:?}; {:?}",driver.status()));assert_eq!(status.phase,Phase::AwaitingVerification);assert_eq!(status.round,2,"{status:?}");assert_eq!(r.base.decisions.load(Ordering::Acquire),3);let done=current_store(&r.s).read(&r.g.id,&r.g.spec.owner.pet_id).unwrap();assert!(done.completion.is_none());assert_eq!(done.generated_plans,r.g.generated_plans);let b=body(&r.s,&done);assert_eq!(b["planningUsage"]["rounds"][1]["publication"]["phase"],"acknowledged");assert_eq!(b["planningUsage"]["rounds"],{let mut rounds=before["planningUsage"]["rounds"].clone();rounds[1]["publication"]["phase"]=json!("acknowledged");rounds});assert_eq!(b["messages"]["entries"].as_array().unwrap().len(),2);assert_eq!(r.requests.len(),4);assert_eq!(r.o.workers(),0);
}}
#[test]fn recreated_driver_reviews_only_undelivered_steps_and_never_replays_a_canonical_receipt(){for p in["ollama","lmstudio"]{
 let r=prepare(p,2,true);let lineage=r.o.reconcile_peer_round_plan(Arc::new(current_store(&r.s)),&r.request,crate::assistant_memory::now()).unwrap();assert!(lineage.reconciled());assert!(!lineage.retains_native_data_approval());let approved=approve_batch(&r,lineage);let first=r.o.send_message(&r.g,&approved[0],crate::assistant_memory::now(),||Ok((r.s.config.clone(),r.s.settings.clone()))).unwrap();drop(approved);let before=body(&r.s,&r.g);let driver=Driver::new(r.o.clone(),Arc::new(current_store(&r.s)),Arc::new(Env{base:r.base.clone(),pending:1,delivered:1})).unwrap();assert_eq!(run(driver.run()).unwrap().phase,Phase::AwaitingVerification);assert_eq!(r.base.decisions.load(Ordering::Acquire),4);let done=current_store(&r.s).read(&r.g.id,&r.g.spec.owner.pet_id).unwrap();let after=body(&r.s,&done);assert_eq!(after["messages"]["entries"].as_array().unwrap().len(),3);assert_eq!(after["budgetUsage"]["attempts"].as_array().unwrap().len(),before["budgetUsage"]["attempts"].as_array().unwrap().len()+1);let bytes=r.s.bytes(&done);assert_eq!(r.s.a.message_ack(&r.o.live.spec,&r.o.live.proof,&first.scope).unwrap().as_ref(),Some(&first));assert_eq!(r.s.bytes(&done),bytes);assert_eq!(r.requests.len(),4);assert_eq!(r.o.workers(),0);
}}
#[test]fn recovered_lineage_is_exact_expiring_and_latches_changed_history_without_constructing_model_approval(){
 let r=prepare("ollama",1,true);let row=&r.g.admissions[0];let b=body(&r.s,&r.g);let data:crate::pet_runtime::peer_round_data::Consent=serde_json::from_value(b["planningUsage"]["rounds"][1]["peerData"].clone()).unwrap();assert!(r.s.a.reconciled_peer_publication(&row.spec,row.proof.as_ref().unwrap(),r.o.lease(),&r.g,&r.request,data.expires_at).is_err());let mut wrong=r.o.lease().clone();wrong.controller_id=nonce().unwrap();assert!(r.s.a.reconciled_peer_publication(&row.spec,row.proof.as_ref().unwrap(),&wrong,&r.g,&r.request,crate::assistant_memory::now()).is_err());let scope=r.o.reconcile_peer_round_plan(Arc::new(current_store(&r.s)),&r.request,crate::assistant_memory::now()).unwrap();assert_eq!(scope.expires_at(),data.expires_at);assert_eq!(scope.current(),Validity::Current);let id=b["planningUsage"]["rounds"][0]["attemptId"].as_str().unwrap();let path=r.s.a.result_root().unwrap().join(&row.spec.decision_id).join(format!("{id}.json"));let raw=fs::read(&path).unwrap();fs::write(&path,b"corrupt private canonical own model result").unwrap();assert_eq!(scope.current(),Validity::Changed);fs::write(path,raw).unwrap();assert_eq!(scope.current(),Validity::Changed);assert_eq!(scope.metadata_current(),Validity::Changed);assert_eq!(r.base.decisions.load(Ordering::Acquire),2);
}
#[test]fn staged_unpublished_envelope_refuses_new_approval_and_only_original_native_scope_can_reconcile_it(){
 let r=prepare("ollama",1,true);let scope=r.o.reconcile_peer_round_plan(Arc::new(current_store(&r.s)),&r.request,crate::assistant_memory::now()).unwrap();let approved=approve_batch(&r,scope);let before=body(&r.s,&r.g);let mut a=crate::pet_runtime::authority::Authority::existing(&r.s.f.path.join("authority")).unwrap();a.fault=crate::pet_runtime::authority_store::Fault::BeforeGrantPublish;assert!(a.deliver_message(&r.g,&r.o.live.spec,&r.o.live.proof,r.o.lease(),&approved[0],crate::assistant_memory::now(),||true).is_err());let lineage=r.o.reconcile_peer_round_plan(Arc::new(current_store(&r.s)),&r.request,crate::assistant_memory::now()).unwrap();assert!(peer_plan_review::Batch::capture_with_round(&r.o,&r.g,&r.s.config,&r.s.settings,crate::assistant_memory::now(),Some(lineage)).is_err());assert_eq!(body(&r.s,&r.g),before);let receipt=r.o.send_message(&r.g,&approved[0],crate::assistant_memory::now(),||Ok((r.s.config.clone(),r.s.settings.clone()))).unwrap();let after=body(&r.s,&r.g);assert_eq!(after["messages"]["entries"].as_array().unwrap().len(),2);assert_eq!(r.s.a.message_ack(&r.o.live.spec,&r.o.live.proof,&receipt.scope).unwrap().as_ref(),Some(&receipt));assert_eq!(r.base.decisions.load(Ordering::Acquire),3);
}

